NS_IMETHODIMP ExchangeFolder::CopyMessages(
    nsIMsgFolder* aSrcFolder, nsTArray<RefPtr<nsIMsgDBHdr>> const& aSrcHdrs,
    bool aIsMove, nsIMsgWindow* aMsgWindow,
    nsIMsgCopyServiceListener* aCopyListener, bool aIsFolder, bool aAllowUndo) {
  NS_ENSURE_ARG_POINTER(aSrcFolder);

  nsresult rv = NS_OK;

  auto notifyFailureOnExit = GuardCopyServiceExit(aSrcFolder, this, rv);

  // Make sure we're not moving/copying to the root folder for the server,
  // since it cannot hold messages.
  bool isServer;
  MOZ_TRY(GetIsServer(&isServer));
  if (isServer) {
    NS_ERROR("Destination is the root folder. Cannot move/copy here");
    return NS_ERROR_FILE_COPY_OR_MOVE_FAILED;
  }

  bool isSameServer = false;
  rv = FoldersOnSameServer(aSrcFolder, this, &isSameServer);
  NS_ENSURE_SUCCESS(rv, rv);

  if (isSameServer) {
    // Since the folders are on the same (Exchange) server, the other folder
    // must also be an Exchange Folder.
    nsCOMPtr<IExchangeFolder> exchangeSourceFolder{
        do_QueryInterface(aSrcFolder, &rv)};
    NS_ENSURE_SUCCESS(rv, rv);
    const auto undoType =
        aIsMove ? nsIMessenger::eMoveMsg : nsIMessenger::eCopyMsg;
    rv = CopyItemsOnSameServer(exchangeSourceFolder, aSrcHdrs, aIsMove,
                               aMsgWindow, aCopyListener, aAllowUndo, undoType,
                               nullptr);
    NS_ENSURE_SUCCESS(rv, rv);
  } else {
    // Cross-server copy or move. Instantiate a `ExchangeMessageCopyHandler` for
    // this operation.
    nsCString exchangeId;
    nsresult rv = GetExchangeId(exchangeId);
    NS_ENSURE_SUCCESS(rv, rv);

    nsCOMPtr<IExchangeClient> client;
    MOZ_TRY(GetProtocolClient(getter_AddRefs(client)));

    RefPtr<ExchangeMessageCopyHandler> handler = new ExchangeMessageCopyHandler(
        aSrcFolder, this, aSrcHdrs, aIsMove, aMsgWindow, exchangeId, client,
        aCopyListener);

    // Start the copy for the first message. Once this copy has finished, the
    // `ExchangeMessageCopyHandler` will automatically start the copy for the
    // next message in line, and so on until every message in `srcHdrs` have
    // been copied.
    rv = handler->StartCopyingNextMessage();
    if (NS_FAILED(rv)) {
      // If setting up the operation has failed, send the relevant notifications
      // before exiting.
      handler->OnCopyCompleted(rv);
    }

    NS_ENSURE_SUCCESS(rv, rv);
  }
